/// Removes the folder `dir`, if empty: on Windows, a file just removed may
/// linger a moment, as another program still has it open, so it is tried
/// again for a little while.
fn remove_dir(dir: &Path) -> bool {
    let tries = if cfg!(windows) { 20 } else { 1 };
    for _ in 0..tries {
        if std::fs::remove_dir(dir).is_ok() {
            return true;
        }
        // Not empty of anything but what is still going: given up at once.
        let lingering = std::fs::read_dir(dir).is_ok_and(|entries| entries.count() <= 1);
        if !lingering {
            return false;
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    false''')
